"""load_player, score_players and open_curve_runs on samples and doubles (PL-03 step 1, PL-04)."""

import importlib.util
from pathlib import Path

import numpy as np
import pytest

from rllab.core import SOLO, RunSettings, Transition
from rllab.evaluate import ScoreSet
from rllab.lab import players
from rllab.lab.types import PlayerTarget, ReportTargets
from rllab.runs import GameRecording, RunRecord

pytestmark = pytest.mark.unit

CONTRACTS = Path(__file__).parents[2] / "contracts"
_spec = importlib.util.spec_from_file_location("contracts_codec", CONTRACTS / "codec.py")
assert _spec is not None
assert _spec.loader is not None
codec = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(codec)


class LoadingAgent:
    """A player that only remembers the checkpoints it was loaded from."""

    def __init__(self) -> None:
        self.loaded: list[Path] = []

    def act(self, obs: np.ndarray, *, explore: bool) -> np.ndarray:
        return np.zeros(len(obs), dtype=np.int64)

    def learn(self, t: Transition) -> None:
        raise AssertionError("a scored player never learns")

    def save(self, path: Path) -> None:
        path.write_text("", encoding="utf-8")

    def load(self, path: Path) -> None:
        self.loaded.append(path)


class Doubles:
    """Stands in for runs.open_run, make_env, make_agent and evaluate; records what they got."""

    def __init__(self, monkeypatch: pytest.MonkeyPatch, record: RunRecord) -> None:
        self.envs: list[RunSettings] = []
        self.agents: list[dict[str, LoadingAgent]] = []
        self.made_for: list[RunSettings] = []
        raw = codec.samples("evaluate.evaluate")["scripted_seed0"]
        self.scores = codec.build(ScoreSet, raw["scores"])
        game = codec.build(GameRecording, raw["game"])
        monkeypatch.setattr(players, "open_run", codec.fake("runs.open_run").make_open_run(record))
        monkeypatch.setattr(players, "make_env", self.make_env)
        monkeypatch.setattr(players, "make_agent", self.make_agent)
        monkeypatch.setattr(
            players, "evaluate", codec.fake("evaluate.evaluate").make_evaluate(self.scores, game)
        )

    def make_env(self, settings: RunSettings):
        self.envs.append(settings)
        return lambda: settings.env

    def make_agent(self, settings: RunSettings, env: object) -> dict[str, LoadingAgent]:
        assert env == settings.env
        self.made_for.append(settings)
        teams = settings.opponents or {SOLO: "learn"}
        agents = {team: LoadingAgent() for team in teams}
        self.agents.append(agents)
        return agents


def _record(case: str) -> RunRecord:
    return codec.sample("runs.RunRecord", case, RunRecord)


def _run_folder(tmp_path: Path, name: str) -> Path:
    folder = tmp_path / name
    folder.mkdir()
    (folder / "settings.json").write_text("{}", encoding="utf-8")
    return folder


def test_run_folder_loads_its_checkpoint_into_the_run_agent(monkeypatch, tmp_path):
    record = _record("corridor_complete")
    doubles = Doubles(monkeypatch, record)
    folder = _run_folder(tmp_path, "corridor")

    agents, settings = players.load_player(str(folder), 0)

    assert settings == record.settings
    assert doubles.made_for == [record.settings]
    assert list(agents) == [SOLO]
    assert agents[SOLO].loaded == [record.checkpoints[SOLO]]


def test_run_folder_loads_every_team_checkpoint(monkeypatch, tmp_path):
    record = _record("predprey_rung3")
    Doubles(monkeypatch, record)

    agents, _ = players.load_player(str(_run_folder(tmp_path, "rung3")), 0)

    assert agents["predator"].loaded == [record.checkpoints["predator"]]
    assert agents["prey"].loaded == [record.checkpoints["prey"]]


def test_run_without_a_checkpoint_raises_naming_the_run(monkeypatch, tmp_path):
    Doubles(monkeypatch, _record("snake_incomplete"))
    folder = _run_folder(tmp_path, "unfinished")

    with pytest.raises(ValueError, match=r"unfinished: no checkpoint \(status incomplete\)"):
        players.load_player(str(folder), 2)


def test_missing_run_folder_raises_file_not_found(monkeypatch, tmp_path):
    Doubles(monkeypatch, _record("corridor_complete"))

    with pytest.raises(FileNotFoundError, match="absent"):
        players.load_player(str(tmp_path / "absent"), 0)


@pytest.mark.parametrize("name", ["random", "scripted"])
def test_baseline_name_plays_default_snake_compact_on_the_seed(monkeypatch, name):
    doubles = Doubles(monkeypatch, _record("corridor_complete"))

    agents, settings = players.load_player(name, 3)

    assert (settings.env, settings.view, settings.agent) == ("snake", "compact", name)
    assert (settings.n_agents, settings.opponents, settings.ablation) == (1, {}, "none")
    assert settings.seed == 3
    assert doubles.made_for == [settings]
    assert agents is doubles.agents[0]
    assert agents[SOLO].loaded == []


def test_score_players_gives_one_score_set_per_player_and_seed(monkeypatch, tmp_path):
    record = _record("corridor_complete")
    doubles = Doubles(monkeypatch, record)
    first, second = _run_folder(tmp_path, "s0"), _run_folder(tmp_path, "s1")
    targets = ReportTargets(
        players=(
            PlayerTarget(name="tabular", targets=(str(first), str(second)), seeds=(0, 1)),
            PlayerTarget(name="random", targets=("random",), seeds=(4,)),
        ),
        baselines=("random",),
        ladder=("tabular",),
        ablations={},
    )

    scores = players.score_players(targets)

    assert list(scores) == ["tabular", "random"]
    assert [(s.player, s.train_seed) for s in scores["tabular"]] == [("tabular", 0), ("tabular", 1)]
    assert [(s.player, s.train_seed) for s in scores["random"]] == [("random", 4)]
    for score_set in (*scores["tabular"], *scores["random"]):
        assert score_set.scores.tolist() == doubles.scores.scores.tolist()
        assert score_set.games == ()
    agents_built = [s.agent for s in doubles.envs]
    assert agents_built == ["tabular"] * 4 + ["random"] * 2


def test_score_players_refuses_a_seed_count_unlike_its_targets(monkeypatch, tmp_path):
    Doubles(monkeypatch, _record("corridor_complete"))
